import{_ as l,o as e,c as o,ab as t}from"./chunks/framework.DCf1Sbhf.js";const f=JSON.parse('{"title":"核心","description":"","frontmatter":{},"headers":[],"relativePath":"front/micro/wujie/index.md","filePath":"front/micro/wujie/index.md","lastUpdated":1776041122000}'),r={name:"front/micro/wujie/index.md"};function n(a,i,u,m,d,p){return e(),o("div",null,[...i[0]||(i[0]=[t('<p>官网：<a href="https://wujie-micro.github.io/doc/" target="_blank" rel="noreferrer">https://wujie-micro.github.io/doc/</a></p><h1 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to &quot;核心&quot;">​</a></h1><p>无界基于 <code>iframe</code> + <code>WebComponent</code> 原生能力实现微前端</p><ol><li>JS 沙箱与应用加载机制 <ul><li>将子应用 JS 注入主应用同域 iframe运行，依托 iframe 原生window沙箱实现 JS 隔离</li><li>子应用实例运行在 iframe 内，不污染主应用window，无需修改主应用环境</li><li>组件化使用微前端，无需注册、无需路由适配，随组件装载 / 卸载</li></ul></li><li>路由同步机制 <ul><li>利用浏览器joint session history，iframe 的history与主应用同源共享</li><li>劫持iframe.history.pushState/replaceState，将子应用路由同步到主应用query参数</li><li>刷新 / 前进 / 后退自动作用于子应用，多应用同时激活也可保持路由同步</li></ul></li><li>CSS 沙箱与 DOM 连接机制 <ul><li>基于WebComponent创建wujie自定义元素，实现 CSS 物理隔离</li><li>代理 iframe 的document查询接口到 WebComponent，打通子应用实例与 DOM 渲染</li><li>支持子应用保活（keep-alive），切换时保留 iframe 与 WebComponent，状态不丢失</li><li>弹窗自动代理到 WebComponent，无需子应用改造</li></ul></li><li>应用通信机制 <ul><li>Props 注入：子应用通过$wujie.props获取主应用数据</li><li>同源通信：iframe 与主应用同域，子应用可直接用window.parent通信</li><li>EventBus：去中心化事件总线，主 / 子应用全链路互通</li></ul></li><li>性能与优化技术 <ul><li>预加载preload提前实例化 iframe，降低初始化开销</li><li>子应用执行性能与原生一致，无with(proxyWindow)性能损耗</li><li>轻量体积，依托原生 API 实现沙箱，减少框架代码量</li></ul></li><li>子应用保活（Alive）技术 <ul><li>切换时保留 iframe 实例 + WebComponent 节点，不销毁</li><li>子应用状态、DOM、JS 上下文完全留存</li><li>回归时直接挂载 WebComponent，实现类 keep-alive 效果</li><li>配合预执行，达到接近 SSR 的秒开体验</li></ul></li><li>生命周期管理 <ul><li>内置完备生命周期：before-load、loaded、before-mount、mounted、before-unmount、unmounted、error</li><li>主 / 子应用可通过生命周期做加载控制、数据注入、清理逻辑等</li></ul></li><li>插件系统 <ul><li>提供插件机制扩展框架能力</li><li>可拦截子应用加载、运行、卸载全流程</li><li>支持日志、监控、权限、资源处理等横向能力注入</li></ul></li><li>降级处理（Degrade） <ul><li>不支持 WebComponent/iframe 场景自动优雅降级</li><li>保证老旧浏览器 / 特殊环境下基础可用</li></ul></li><li>应用嵌套（Nest） <ul><li>支持子应用再嵌套子应用，多层级微前端架构</li><li>沙箱、路由、通信机制递归生效，无嵌套冲突</li></ul></li><li>应用共享（Share） <ul><li>支持公共依赖 / 组件 / 库跨应用共享</li><li>减少重复加载，提升整体性能</li></ul></li><li>多应用并行激活 <ul><li>同一页面同时激活多个子应用，互不干扰</li><li>各自路由独立，不抢占主应用路由</li><li>多 iframe + 多 WebComponent 并行运行</li></ul></li><li>原生隔离兜底 <ul><li>JS 隔离：同域 iframe 原生沙箱，无 Proxy 性能损耗</li><li>CSS 隔离：WebComponent 原生样式隔离，无样式穿透</li><li>DOM 隔离：document 全量代理，弹窗、挂载自动收敛到容器</li></ul></li></ol>',4)])])}const c=l(r,[["render",n]]);export{f as __pageData,c as default};
